INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-08-05' FROM countries WHERE name_en = 'Ecuador';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'en', 'Clearance-style CTC via self-computed authorization keys, with near-instantaneous SRI validation', 'This deep-dive page reflects publicly available SRI resolutions and industry reporting as of early August 2026 and is provided for general awareness, not legal or tax advice. Confirm current requirements directly with SRI or an Ecuadorian tax adviser before relying on this page for compliance decisions.', 'Ecuador''s SRI has required near-real-time e-invoice validation since 2014, reaching effectively universal coverage by late 2022. January 2026''s headline change wasn''t the introduction of real-time reporting -- it closed a temporary relaxation granted during the country''s 2024 electrical emergency, reverting to the standing immediate-transmission rule.', 'Invoices are issued as XML per SRI''s published XSD schemas. The issuer self-computes a 49-digit access code (clave de acceso) built from the date, document type, RUC, environment, establishment, emission point, sequential number, a random component, emission type, and a check digit, then applies a mandatory Advanced Electronic Signature (Firma Electrónica Avanzada / XAdES-BES) before submitting to SRI. A printed representation (RIDE), carrying a GS1-128 barcode, is required whenever the recipient can''t or won''t accept the XML directly.', 'Ecuador''s e-invoicing mandate is effectively universal for VAT-registered taxpayers, following a phased rollout that reached ~100% coverage by late 2022 -- but one real carve-out remains: RIMPE ''Negocios Populares'' taxpayers (income up to $20,000) are exempt and may still use paper ''notas de venta RISE''. Only RIMPE ''Emprendedores'' (up to $300,000) and larger taxpayers are actually obligated to issue electronic invoices, so don''t assume every Ecuadorian counterparty is in scope.', 'Because the January 2026 transmission-window change is recent, most businesses have real implementation work ahead confirming their systems transmit immediately again rather than relying on the now-eliminated emergency window, and that their cancellation workflows reflect the shortened deadline.', 'Ecuador backs its e-invoicing rules with a real, sourced penalty schedule denominated in Remuneración Básica Unificada (RBU) -- Ecuador''s basic unified wage, confirmed at USD $482 for 2026 -- that scales sharply by taxpayer category, from large taxpayers down to unregistered persons.', 'Ecuador''s SRI has required near-real-time e-invoice transmission since 2014, reaching effectively universal coverage among VAT taxpayers by late 2022 (RIMPE Negocios Populares excepted). A temporary 4-business-day grace period granted during the 2024 electrical-emergency crisis was closed on 1 January 2026, restoring the standing immediate-transmission rule. The model is best described as clearance-style: issuers self-compute a 49-digit authorization key, and SRI''s automated validation -- typically completing within seconds -- is required for legal validity.', '🇪🇨' FROM countries WHERE name_en = 'Ecuador';
