INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Ecuador';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Format, keys & validation', '[["Format", "XML, per SRI''s published XSD schemas"], ["Authorization key", "Self-computed 49-digit access code (clave de acceso): date, document type, RUC, environment, establishment, emission point, sequential number, random component, emission type, and a check digit"], ["Digital signature", "Mandatory Advanced Electronic Signature (Firma Electrónica Avanzada / XAdES-BES)"], ["SRI validation", "Automated; typically completes within seconds and is required for legal validity"]]', 'Some vendor sources describe a stricter SRI-approves-first-then-delivery sequence; others describe deliver-immediately-with-parallel-authorization, where the invoice becomes ''definitivo'' once SRI authorizes it. This is a genuine unresolved ambiguity in secondary sources -- in practice, most implementations treat this as a clearance sequence, since SRI''s validation is normally near-instantaneous and required before an invoice is legally valid.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Ecuador';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'RIDE, retention & delivery', '[["RIDE", "Representación Impresa de Documento Electrónico -- a printed representation carrying a GS1-128 barcode, required when the recipient can''t or won''t accept the XML directly"], ["Delivery", "XML delivered directly to the buyer, or RIDE where a printed/visual copy is required"], ["Retention", "Minimum 7 years, for both issuer and recipient"], ["Governing body", "Servicio de Rentas Internas (SRI)"]]', NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Ecuador';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Document family', '[["Facturas", "Standard invoices"], ["Comprobantes de retención", "Withholding/retention vouchers"], ["Guías de remisión", "Remission guides -- documentation for goods in transit"], ["Notas de crédito / débito", "Credit notes and debit notes"], ["Liquidaciones de compra", "Purchase liquidations"]]', NULL, NULL);
INSERT INTO deep_dive_lifecycle_cards (country_id, section, sort_order, display_style) SELECT id, 'scope_transmission', 0, 'pills' FROM countries WHERE name_en = 'Ecuador';
INSERT INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 'en', 'The self-computed clearance flow', 'An Ecuadorian e-invoice moves through this sequence -- the issuer does the initial computation, but SRI''s authorization is what makes the document valid:', 'SRI''s automated validation normally completes within seconds -- treat authorization as a required, near-immediate step in issuance, not a background formality.');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 0, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Issuer generates the XML invoice and self-computes its 49-digit access code (clave de acceso)');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 1, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Issuer applies the mandatory Advanced Electronic Signature (XAdES-BES)');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 2, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Signed XML is submitted to SRI for automated validation');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 3, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'SRI authorizes the document -- typically within seconds -- assigning the número de autorización');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 4, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Authorized invoice is delivered to the buyer, as XML or as RIDE where a printed copy is required');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Ecuador';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Who''s actually in scope', '[["General VAT-registered taxpayers", "In scope, following the phased 2014-2022 rollout that reached effective universality"], ["RIMPE Emprendedores", "In scope (income up to $300,000)"], ["RIMPE Negocios Populares", "EXEMPT -- income up to $20,000; may still use paper notas de venta RISE"], ["Foreign/non-resident suppliers", "Come into scope on registering for Ecuadorian tax purposes"]]', 'Effectively universal outside the Negocios Populares carve-out -- don''t assume literally every Ecuadorian counterparty is on electronic invoicing.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Ecuador';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Transmission-window history', '[["2014-2018", "Immediate, at the moment of the transaction"], ["2018-2024", "Immediate, or up to 72 hours for high-volume issuers"], ["Nov 2024-Dec 2025", "Immediate, or up to 4 business days -- temporary electrical-emergency relief"], ["From 1 Jan 2026", "Immediate again -- the 4-business-day allowance was eliminated"]]', 'The January 2026 change closes a temporary relaxation granted during Ecuador''s 2024 electrical emergency -- it restores, rather than introduces, a near-real-time transmission requirement that has applied since 2014.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Ecuador';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '💰 Penalties are set in RBU and scale sharply by taxpayer category', NULL, NULL, 'SRI''s Resolution NAC-DGERCGC24-00000022 (6 June 2024) sets penalties in Remuneración Básica Unificada (RBU) -- Ecuador''s basic unified wage, confirmed at USD $482 for 2026 -- with separate, higher figures for failing to transmit an invoice than for failing to deliver one, and a schedule that scales sharply by category, from large taxpayers down to unregistered persons. See the penalty table below for representative figures.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Ecuador';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🔒 Consumidor final invoices are now non-cancellable', NULL, NULL, 'From 1 January 2026, invoices issued to ''consumidor final'' can no longer be cancelled, alongside a shortened cancellation-window deadline -- moved from the 10th to the 7th of the following month by Resolution NAC-DGERCGC25-00000017. Businesses that routinely cancelled or corrected final-consumer invoices after the fact need a different process now.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Ecuador';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '⚠️ The Negocios Populares carve-out doesn''t mean zero risk', NULL, NULL, 'Even Ecuador''s smallest taxpayer category isn''t penalty-free: RIMPE Negocios Populares still faces a 1 RBU fine (about $482) for either non-delivery or non-transmission failures, despite being exempt from the electronic-invoicing mandate itself and permitted to use paper notas de venta RISE.');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Ecuador';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Large taxpayers (grandes contribuyentes y grandes patrimonios) -- non-delivery / non-transmission', '$9,640 / $14,460 (20 RBU / 30 RBU)', '—');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Ecuador';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Special taxpayers (contribuyentes especiales) -- non-delivery / non-transmission', '$4,820 / $7,230 (10 RBU / 15 RBU)', '—');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Ecuador';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'General companies obligated to keep accounting records -- non-delivery / non-transmission', '$3,374 / $4,820 (7 RBU / 10 RBU)', '—');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Ecuador';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'RIMPE Negocios Populares -- non-delivery / non-transmission', '$482 / $482 (1 RBU / 1 RBU)', '—');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Ecuador';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm which taxpayer category applies to your business', 'Both scope and penalty exposure depend on whether you''re a large taxpayer, special taxpayer, a general company, or fall under RIMPE Emprendedores or Negocios Populares -- confirm your category with SRI or a local adviser before relying on any generic figure.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Ecuador';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm your invoicing software correctly generates the 49-digit access code and applies XAdES-BES signing', 'A malformed access code or missing Advanced Electronic Signature will cause SRI to reject the invoice outright -- verify both before going live with any new system.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Ecuador';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Build a real-time SRI-authorization check into your issuance process', 'Don''t treat a self-computed access code alone as a valid invoice -- SRI''s authorization, normally received within seconds, is what actually makes the document legally valid.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Ecuador';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Update your systems to immediate transmission', 'The 4-business-day emergency window granted in November 2024 no longer applies as of 1 January 2026 -- confirm your invoicing pipeline transmits to SRI immediately, not on the now-eliminated delayed schedule.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Ecuador';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Adjust invoice-cancellation workflows for consumidor final documents', 'Consumidor final invoices became non-cancellable from 1 January 2026, and the general cancellation-window deadline moved from the 10th to the 7th of the following month -- update your processes to match.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 5 FROM countries WHERE name_en = 'Ecuador';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Retain XML and RIDE copies for at least 7 years', 'Both issuer and recipient must retain electronic documents for a minimum of 7 years -- build this into your document-management policy for both issued and received invoices.');
